  .p-progress-spinner-circle { stroke-dasharray: 89, 200; stroke-dashoffset: 0; stroke: rgb(214, 45, 32); animation: 1.5s ease-in-out 0s infinite normal none running p-progress-spinner-dash, 6s ease-in-out 0s infinite normal none running p-progress-spinner-color; stroke-linecap: round; }
